// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { ERC20 } from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import { RedBlackTreeLib } from "solady/utils/RedBlackTreeLib.sol";

/// @notice Fixed supply and a cumulative two-percent receiving budget for the opening five minutes.
/// @dev Selling, burning and forwarding tokens do not refill the budget. No EOA or contract is whitelisted.
contract FeeFlowQaToken is ERC20 {
    uint256 public constant POLICY_REVISION = 2;
    uint256 public constant WALLET_LIMIT_BPS = 200;
    uint256 public constant PROTECTION_SECONDS = 300;
    address public immutable initializer;
    address public immutable poolManager;
    uint256 public immutable launchSupply;
    uint256 public immutable walletTokenLimit;
    uint256 public startedAt;
    mapping(address => uint256) public receivedDuringProtection;

    address public hook;
    address public feeVault;
    address public constant burnAddress = 0x000000000000000000000000000000000000dEaD;
    uint256 private constant TOP_HOLDER_COUNT = 10;
    uint256 private constant SNAPSHOT_DAY_SECONDS = 1 days;

    RedBlackTreeLib.Tree private _holderTree;
    mapping(address => uint96) private _holderId;
    mapping(uint96 => address) private _holderAddress;
    uint96 private _nextHolderId;
    mapping(address => bool) public isExcludedHolder;
    uint256 public lastSnapshotDay;

    struct Snapshot {
        uint256 day;
        uint256 total;
        address[10] holders;
        uint256[10] balances;
        mapping(address => uint256) balanceOf;
    }
    uint256 public snapshotCount;
    mapping(uint256 => Snapshot) private _snapshots;

    error HookAlreadyBound();
    error InvalidHook();
    error NotHookCallerOrOwner();

    error InvalidConfiguration();
    error NotInitializer();
    error AlreadyStarted();
    error TradingNotStarted();
    error WalletLimitExceeded(address recipient, uint256 attempted, uint256 limit);

    constructor(string memory name_, string memory symbol_, uint256 supply_, address initializer_, address manager_)
        ERC20(name_, symbol_)
    {
        if (
            bytes(name_).length == 0 || bytes(symbol_).length == 0 || supply_ < 50
                || supply_ > uint256(uint128(type(int128).max)) || initializer_ == address(0)
                || manager_.code.length == 0 || initializer_ == manager_
        ) revert InvalidConfiguration();
        initializer = initializer_;
        poolManager = manager_;
        launchSupply = supply_;
        walletTokenLimit = supply_ * WALLET_LIMIT_BPS / 10_000;
        _mint(initializer_, supply_);
    }

    function start() external {
        if (msg.sender != initializer) revert NotInitializer();
        if (startedAt != 0) revert AlreadyStarted();
        if (block.timestamp == 0) revert InvalidConfiguration();
        startedAt = block.timestamp;
        lastSnapshotDay = currentUtcDay();
    }

    function bindHook(address hook_) external {
        if (hook != address(0)) revert HookAlreadyBound();
        if (startedAt != 0 || !IInitializerWindow(initializer).initialized()) revert InvalidConfiguration();
        if (hook_ == address(0) || hook_.code.length == 0 || msg.sender != hook_) revert InvalidHook();
        if (IHookViews(hook_).token() != address(this) || IHookViews(hook_).poolManager() != poolManager
            || IHookViews(hook_).initializer() != initializer) revert InvalidHook();
        hook = hook_;
        feeVault = IHookViews(hook_).feeVault();
        if (feeVault == address(0)) revert InvalidHook();
        isExcludedHolder[hook_] = true;
        isExcludedHolder[poolManager] = true;
        isExcludedHolder[burnAddress] = true;
        isExcludedHolder[feeVault] = true;
        isExcludedHolder[initializer] = true;
        isExcludedHolder[IHookViews(hook_).liquidityVault()] = true;
        _reindex(IHookViews(hook_).liquidityVault());
        _reindex(initializer);
        _reindex(poolManager);
        _reindex(hook_);
        _reindex(feeVault);
    }

    function burn(uint256 amount) external {
        _burn(msg.sender, amount);
    }

    function currentUtcDay() public view returns (uint256) {
        return block.timestamp / SNAPSHOT_DAY_SECONDS;
    }

    function topHolderCount() external view returns (uint256) {
        uint256 n = RedBlackTreeLib.size(_holderTree);
        return n < TOP_HOLDER_COUNT ? n : TOP_HOLDER_COUNT;
    }

    function topHolders() public view returns (address[10] memory addrs, uint256[10] memory bals) {
        return _collectTop();
    }

    function finalizeSnapshot() external {
        _finalizeIfNewDay();
    }

    function snapshotDay(uint256 id) external view returns (uint256) {
        return _snapshots[id].day;
    }

    function snapshotTotal(uint256 id) external view returns (uint256) {
        return _snapshots[id].total;
    }

    function snapshotHolders(uint256 id) external view returns (address[10] memory, uint256[10] memory) {
        return (_snapshots[id].holders, _snapshots[id].balances);
    }

    function snapshotBalanceOf(uint256 id, address account) external view returns (uint256) {
        return _snapshots[id].balanceOf[account];
    }

    function _collectTop() internal view returns (address[10] memory addrs, uint256[10] memory bals) {
        bytes32 ptr = RedBlackTreeLib.last(_holderTree);
        uint256 i;
        while (ptr != bytes32(0) && !RedBlackTreeLib.isEmpty(ptr) && i < TOP_HOLDER_COUNT) {
            uint256 key = RedBlackTreeLib.value(ptr);
            uint96 id = uint96(key & type(uint96).max);
            address a = _holderAddress[id];
            if (!isExcludedHolder[a] && balanceOf(a) != 0) {
                addrs[i] = a;
                bals[i] = balanceOf(a);
                unchecked { ++i; }
            }
            ptr = RedBlackTreeLib.prev(ptr);
        }
    }

    function _finalizeIfNewDay() internal {
        uint256 day = currentUtcDay();
        if (day == lastSnapshotDay) return;
        uint256 id = snapshotCount;
        Snapshot storage s = _snapshots[id];
        s.day = lastSnapshotDay;

        (address[10] memory a, uint256[10] memory b) = _collectTop();
        s.holders = a;
        s.balances = b;
        for (uint256 j; j < TOP_HOLDER_COUNT; ++j) s.total += b[j];
        for (uint256 j; j < TOP_HOLDER_COUNT; ++j) {
            if (a[j] != address(0)) s.balanceOf[a[j]] = b[j];
        }
        unchecked { snapshotCount = id + 1; }
        lastSnapshotDay = day;
        IHookViews(hook).onHolderSnapshot(s.day, s.total);
    }

    // Equal balances rank by descending immutable first-seen id (newest first); all non-excluded holders remain indexed.
    function _holderKey(address account, uint256 bal) private view returns (uint256) {
        return (bal << 96) | uint256(_holderId[account]);
    }

    function _trackHolder(address account) private {
        if (_holderId[account] == 0 && account != address(0)) {
            uint96 id = ++_nextHolderId;
            _holderId[account] = id;
            _holderAddress[id] = account;
        }
    }

    function _update(address from, address to, uint256 amount) internal override {
        if (from != address(0) && to != address(0) && amount != 0) {
            if (startedAt == 0) {
                // Only seed settlement may move inventory before the atomic start.
                if (from != initializer || to != poolManager) revert TradingNotStarted();
            } else if (block.timestamp < startedAt + PROTECTION_SECONDS && to != poolManager) {
                // Self-transfers cannot mint headroom, and should not consume it either.
                if (from != to) {
                    uint256 received = receivedDuringProtection[to] + amount;
                    if (received > walletTokenLimit) revert WalletLimitExceeded(to, received, walletTokenLimit);
                    receivedDuringProtection[to] = received;
                }
            }
        }
        if (startedAt != 0 && amount != 0) {
            _finalizeIfNewDay();
        }
        super._update(from, to, amount);
        if (from != address(0)) _reindex(from);
        if (to != address(0)) _reindex(to);
    }

    function _reindex(address account) private {
        _trackHolder(account);
        uint96 id = _holderId[account];
        uint256 bal = balanceOf(account);
        // Remove old key: stored key is derived from previous balance; tree only holds live entries.
        uint256 oldKey = _lastKey[id];
        if (oldKey != 0) {
            RedBlackTreeLib.remove(_holderTree, oldKey);
            _lastKey[id] = 0;
        }
        if (bal != 0 && !isExcludedHolder[account]) {
            uint256 k = _holderKey(account, bal);
            RedBlackTreeLib.insert(_holderTree, k);
            _lastKey[id] = k;
        }
    }

    mapping(uint96 => uint256) private _lastKey;
}

interface IInitializerWindow {
    function initialized() external view returns (bool);
}

interface IHookViews {
    function onHolderSnapshot(uint256 day,uint256 total) external;
    function liquidityVault() external view returns (address);
    function feeVault() external view returns (address);
    function poolManager() external view returns (address);
    function initializer() external view returns (address);
    function token() external view returns (address);
}

