import {CreatorV4LiquidityVaultV1} from "src/fqa/CreatorV4LiquidityVaultV1.sol";
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { SafeCast } from "@openzeppelin/contracts/utils/math/SafeCast.sol";
import { BaseHook } from "@openzeppelin/uniswap-hooks/src/base/BaseHook.sol";
import { IPoolManager } from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import { IHooks } from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import { Hooks } from "@uniswap/v4-core/src/libraries/Hooks.sol";
import { LPFeeLibrary } from "@uniswap/v4-core/src/libraries/LPFeeLibrary.sol";
import { BalanceDelta } from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {
    BeforeSwapDelta,
    BeforeSwapDeltaLibrary,
    toBeforeSwapDelta
} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import { Currency } from "@uniswap/v4-core/src/types/Currency.sol";
import { PoolKey } from "@uniswap/v4-core/src/types/PoolKey.sol";
import { SwapParams } from "@uniswap/v4-core/src/types/PoolOperation.sol";
import { BaseLaunchProtectionModuleV1 } from "src/base-custom-v1/BaseLaunchProtectionModuleV1.sol";
import { ProtectedLaunchTokenV1 } from "src/launch-protection/ProtectedLaunchTokenV1.sol";
import { EthereumNativeFeeVaultV3 } from "src/ethereum-native30-v3/EthereumNativeFeeVaultV3.sol";
import { FullMath } from "@uniswap/v4-core/src/libraries/FullMath.sol";
import { StateLibrary } from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import { PoolIdLibrary } from "@uniswap/v4-core/src/types/PoolId.sol";
import { TickMath } from "@uniswap/v4-core/src/libraries/TickMath.sol";
import { IUnlockCallback } from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import { PoolId, PoolIdLibrary } from "@uniswap/v4-core/src/types/PoolId.sol";
import { TransientStateLibrary } from "@uniswap/v4-core/src/libraries/TransientStateLibrary.sol";
import { SwapParams as _SwapParamsAlias } from "@uniswap/v4-core/src/types/PoolOperation.sol";

interface IFeeFlowQaSnapshotToken {
    function finalizeSnapshot() external;
    function snapshotCount() external view returns (uint256);
    function snapshotDay(uint256 id) external view returns (uint256);
    function snapshotTotal(uint256 id) external view returns (uint256);
    function snapshotHolders(uint256 id) external view returns (address[10] memory, uint256[10] memory);
    function snapshotBalanceOf(uint256 id, address account) external view returns (uint256);
}

/// @dev Base-only adapter of the existing launch-protection implementation.
/// @notice Read-only validation interface; this version requires zero LP fees and zero custom module deltas.
/// @dev Implementations must authenticate this kernel as caller. A module never executes in kernel storage.
interface IProtectedNativeFeeModuleV1 {
    function beforeSwap(address sender, PoolKey calldata key, SwapParams calldata params, bytes calldata data)
        external
        view
        returns (bytes4, BeforeSwapDelta, uint24);
    function afterSwap(
        address sender,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata data
    ) external view returns (bytes4, int128);
}

/// @notice Sealed native/token launch kernel with a mandatory immutable protection module and fixed 30-bps fee.
/// @dev Fees round up per trade; the opening surcharge is accounted for separately from normal fees.
///      Only the exact bound PoolKey is covered.
///      ETH-specified partial fills revert. Nonzero custom deltas are unsupported, never silently ignored.
///      Fee-funded swaps run through the immutable auxiliary vault so PoolManager invokes the required callbacks.
interface IFeeFlowQaTokenBinding {
    function bindHook(address hook_) external;
}

contract FeeFlowQaHook is BaseHook, IUnlockCallback {
    CreatorV4LiquidityVaultV1 private immutable _liquidityVault;
    uint8 private constant ACTION_LIQUIDITY = 4;
    uint256 public lastLiquidityAt;
    uint256 public constant minimumLiquidityDeposit = 10000;

    uint256 public constant POLICY_REVISION = 2;
    using SafeCast for uint256;
    using SafeCast for int256;
    using LPFeeLibrary for uint24;

    uint256 public immutable CHAIN_ID;
    address public immutable CANONICAL_POOL_MANAGER;
    address public constant PLATFORM_RECIPIENT = 0xD88539d3c4C460136a733A3Fd60cf6BF269079da;
    uint16 public constant PLATFORM_FEE_BPS = 30;
    uint16 public constant FEE_DENOMINATOR = 10_000;
    bytes32 public constant FEE_PROFILE = keccak256("programmable.protected-native-fee.v1.gross-native.ceil-per-trade");

    struct PoolConfig {
        address token;
        uint24 lpFee;
        int24 tickSpacing;
        uint160 initialSqrtPriceX96;
        address initializer;
        address creatorFeeRecipient;
        uint16 creatorBuyFeeBps;
        uint16 creatorSellFeeBps;
        address module;
        uint24 maxModuleLpFeePips;
    }

    address public immutable token;
    uint24 public immutable lpFee;
    int24 public immutable tickSpacing;
    uint160 public immutable initialSqrtPriceX96;
    address public immutable initializer;
    uint16 public immutable creatorBuyFeeBps;
    uint16 public immutable creatorSellFeeBps;
    address public immutable module;
    bytes32 public immutable moduleCodeHash;
    uint24 public immutable maxModuleLpFeePips;
    EthereumNativeFeeVaultV3 public immutable feeVault;
    EthereumNativeFeeVaultV3 public immutable openingTaxVault;
    uint24 private activeOpeningTaxPpm;
    address private projectCreator;
    uint16 public constant projectFeeBps = 100;
    uint256 public totalProjectFeesCollected;
    uint256 public liquidityReserve;
    uint256 public buybackReserve;
    uint256 public holderReserve;
    uint256 public creatorReserve;
    address private activeBuyer;
    mapping(address => uint256) public boughtDuringProtection;
    bool public initialized;
    bool private swapActive;
    bytes32 private activeSwap;
    uint256 private expectedNativePoolAmount;

    uint8 private constant ACTION_NONE = 0;
    uint8 private constant ACTION_CREATOR_CLAIM = 1;
    uint8 private constant ACTION_HOLDER_CLAIM = 2;
    uint8 private constant ACTION_BUYBACK = 3;
    uint256 public lastBuybackAt;
    uint256 public totalBurned;
    uint8 private _actionKind;
    bool private _actionLocked;
    uint256 private _actionAmount;
    address private _actionRecipient;

    mapping(uint256 => uint256) private _holderPoolByDay;
    mapping(uint256 => mapping(address => bool)) public holderClaimed;

    uint16 public constant maxSlippageBps = 100;
    uint256 private constant OBSERVATION_CAPACITY = 64;
    uint256 private constant OBSERVATION_MIN_INTERVAL = 60;
    uint256 private constant TWAP_MIN_AGE = 3600;
    struct Observation {
        uint64 timestamp;
        int128 tickCumulative;
        int24 tick;
        uint160 sqrtPriceX96;
    }
    Observation[64] private _observations;
    uint256 private _observationHead;
    uint256 private _observationStored;
    uint64 private _lastObservedAt;
    int24 private _lastTick;
    int128 private _cumulativeTick;
    bytes32 private _pendingPayoutHash;

    error ActionReentrant();
    error InvalidAction();
    error NothingClaimable();
    error InvalidSnapshot();
    error NotHolderInSnapshot();
    error PaymentFailed();
    error UnauthorizedCallback();

    error InvalidConfiguration();
    error UnexpectedPool();
    error UnauthorizedInitializer();
    error UninitializedPool();
    error ReentrantSwap();
    error InvalidSwapContext();
    error PartialFillUnsupported(uint256 expected, uint256 actual);
    error UnsupportedCustomDelta();
    error InvalidModuleResponse();
    error ModuleCodeChanged();
    error InvalidDynamicFeeOverride();
    error NoTrade();
    error BuyerLimitExceeded(address buyer, uint256 attempted, uint256 limit);

    event NativeFeesAccrued(
        bytes32 indexed poolId,
        address indexed sender,
        bool isBuy,
        uint256 grossNative,
        uint256 platformFee,
        uint256 creatorFee
    );

    event OpeningTaxAccrued(bytes32 indexed poolId, address indexed sender, uint256 grossNative, uint256 amount);

    constructor(
        IPoolManager manager,
        PoolConfig memory config,
        address developer,
        address router,
        bytes32 routerCodeHash,
        address[6] memory exemptWallets
    ) BaseHook(manager) {
        CHAIN_ID = block.chainid;
        CANONICAL_POOL_MANAGER = 0x498581fF718922c3f8e6A244956aF099B2652b2b;
        if (
            block.chainid != 8453 || address(manager) != CANONICAL_POOL_MANAGER || address(manager).code.length == 0
                || config.lpFee != 0 || config.tickSpacing != 60 || config.module != address(0)
                || config.creatorBuyFeeBps > 1000 || config.creatorSellFeeBps > 1000 || config.token == address(0)
                || config.initializer == address(0) || config.creatorFeeRecipient == address(0)
                || config.initialSqrtPriceX96 == 0 || config.tickSpacing <= 0 || config.maxModuleLpFeePips != 0
                || uint256(config.creatorBuyFeeBps) + PLATFORM_FEE_BPS >= FEE_DENOMINATOR
                || uint256(config.creatorSellFeeBps) + PLATFORM_FEE_BPS >= FEE_DENOMINATOR
        ) revert InvalidConfiguration();
        config.lpFee.getInitialLPFee();
        if (
            ProtectedLaunchTokenV1(config.token).initializer() != config.initializer
                || ProtectedLaunchTokenV1(config.token).poolManager() != address(manager)
        ) {
            revert InvalidConfiguration();
        }
        token = config.token;
        projectCreator = config.creatorFeeRecipient;
        lpFee = config.lpFee;
        tickSpacing = config.tickSpacing;
        initialSqrtPriceX96 = config.initialSqrtPriceX96;
        initializer = config.initializer;
        creatorBuyFeeBps = config.creatorBuyFeeBps;
        creatorSellFeeBps = config.creatorSellFeeBps;
        // Keep the normal fee vault as CREATE child 1 for canonical native-fee proof compatibility.
        feeVault = new EthereumNativeFeeVaultV3(manager, config.creatorFeeRecipient);
        BaseLaunchProtectionModuleV1 protection = new BaseLaunchProtectionModuleV1(
            address(this),
            ProtectedLaunchTokenV1(config.token),
            developer,
            router,
            routerCodeHash,
            config.creatorBuyFeeBps,
            exemptWallets
        );
        module = address(protection);
        moduleCodeHash = address(protection).codehash;
        maxModuleLpFeePips = 0;
        openingTaxVault = new EthereumNativeFeeVaultV3(manager, PLATFORM_RECIPIENT);
        _liquidityVault = new CreatorV4LiquidityVaultV1(manager,address(this),config.token,config.creatorFeeRecipient);
    }

    function getHookPermissions() public pure override returns (Hooks.Permissions memory permissions) {
        permissions.beforeInitialize = true;
        permissions.beforeSwap = true;
        permissions.afterSwap = true;
        permissions.beforeSwapReturnDelta = true;
        permissions.afterSwapReturnDelta = true;
    }

    function poolKey() public view returns (PoolKey memory) {
        return PoolKey(Currency.wrap(address(0)), Currency.wrap(token), lpFee, tickSpacing, IHooks(address(this)));
    }

    /// @notice Quote gross native trade value and fixed-recipient fee allocations, all denominated in wei.
    /// @dev Gross includes platform and creator hook fees. Core LP fees already affect the core trade price.
    ///      Creator rates cannot reduce platform's independent ceil(gross * 30 / 10000) allocation.
    function quoteFees(uint256 amount, bool amountIsNet, bool isBuy)
        public
        view
        returns (uint256 gross, uint256 platformFee, uint256 creatorFee)
    {
        uint256 totalBps = PLATFORM_FEE_BPS + uint256(isBuy ? creatorBuyFeeBps : creatorSellFeeBps);
        gross =
            amountIsNet ? Math.mulDiv(amount, FEE_DENOMINATOR, FEE_DENOMINATOR - totalBps, Math.Rounding.Ceil) : amount;
        uint256 totalFee =
            amountIsNet ? gross - amount : Math.mulDiv(gross, totalBps, FEE_DENOMINATOR, Math.Rounding.Ceil);
        platformFee = Math.mulDiv(gross, PLATFORM_FEE_BPS, FEE_DENOMINATOR, Math.Rounding.Ceil);
        creatorFee = totalFee - platformFee;
    }

    function previewTradeFees(uint256 amount, bool amountIsNet, bool isBuy, address buyer)
        external
        view
        returns (uint256 gross, uint256 platformFee, uint256 creatorFee, uint256 openingTax)
    {
        uint24 taxPpm = isBuy ? BaseLaunchProtectionModuleV1(module).additionalTaxPpmForBuyer(buyer) : 0;
        return _quoteTradeFees(amount, amountIsNet, isBuy, taxPpm);
    }

    function _quoteTradeFees(uint256 amount, bool amountIsNet, bool isBuy, uint24 taxPpm)
        private
        view
        returns (uint256 gross, uint256 platformFee, uint256 creatorFee, uint256 openingTax)
    {
        uint256 normalPpm = (PLATFORM_FEE_BPS + uint256(isBuy ? creatorBuyFeeBps : creatorSellFeeBps)) * 100;
        uint256 totalPpm = normalPpm + taxPpm;
        if (totalPpm >= 1_000_000) revert InvalidConfiguration();
        gross = amountIsNet ? Math.mulDiv(amount, 1_000_000, 1_000_000 - totalPpm, Math.Rounding.Ceil) : amount;
        uint256 totalFee = amountIsNet ? gross - amount : Math.mulDiv(gross, totalPpm, 1_000_000, Math.Rounding.Ceil);
        uint256 normalFee = Math.mulDiv(gross, normalPpm, 1_000_000, Math.Rounding.Ceil);
        platformFee = Math.mulDiv(gross, PLATFORM_FEE_BPS, FEE_DENOMINATOR, Math.Rounding.Ceil);
        creatorFee = normalFee - platformFee;
        openingTax = totalFee - normalFee;
    }

    function _beforeInitialize(address sender, PoolKey calldata key, uint160 price) internal override returns (bytes4) {
        _requirePool(key);
        if (initialized || sender != initializer || price != initialSqrtPriceX96) revert UnauthorizedInitializer();
        initialized = true;
        IFeeFlowQaTokenBinding(token).bindHook(address(this));
        return IHooks.beforeInitialize.selector;
    }

    function _beforeSwap(address sender, PoolKey calldata key, SwapParams calldata params, bytes calldata data)
        internal
        override
        returns (bytes4, BeforeSwapDelta, uint24 overrideFee)
    {
        _requirePool(key);
        if (!initialized) revert UninitializedPool();
        if (_actionLocked && !_internalActionSender(sender)) revert ActionReentrant();
        if (swapActive) revert ReentrantSwap();
        if (params.amountSpecified == 0) revert NoTrade();
        swapActive = true;
        activeSwap = keccak256(abi.encode(sender, key, params, data));
        overrideFee = _beforeModule(sender, key, params, data);
        if (params.zeroForOne && block.timestamp < ProtectedLaunchTokenV1(token).startedAt() + 300) {
            activeBuyer = BaseLaunchProtectionModuleV1(module).protectedBuyer(sender);
        }
        activeOpeningTaxPpm =
            params.zeroForOne && !_internalActionSender(sender) ? BaseLaunchProtectionModuleV1(module).openingTaxPpmForSender(sender) : 0;
        bool nativeIsSpecified = params.zeroForOne == (params.amountSpecified < 0);
        if (!nativeIsSpecified) return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, overrideFee);
        uint256 nativeAmount = _absolute(params.amountSpecified);
        (uint256 gross, uint256 platformFee, uint256 creatorFee, uint256 openingTax) =
            _quoteTradeFees(nativeAmount, params.amountSpecified > 0, params.zeroForOne, activeOpeningTaxPpm);
        uint256 total = platformFee + creatorFee + openingTax;
        if (params.amountSpecified < 0 && total >= nativeAmount) revert NoTrade();
        expectedNativePoolAmount = params.amountSpecified > 0 ? gross : nativeAmount - total;
        if (expectedNativePoolAmount == 0) revert NoTrade();
        _accrue(sender, key, params.zeroForOne, gross, platformFee, creatorFee, openingTax);
        return (IHooks.beforeSwap.selector, toBeforeSwapDelta(total.toInt256().toInt128(), 0), overrideFee);
    }

    function _afterSwap(
        address sender,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata data
    ) internal override returns (bytes4, int128) {
        _requirePool(key);
        if (!swapActive || activeSwap != keccak256(abi.encode(sender, key, params, data))) revert InvalidSwapContext();
        uint256 nativeAmount = _absolute(int256(delta.amount0()));
        if (nativeAmount == 0 || delta.amount1() == 0) revert NoTrade();
        bool nativeIsSpecified = params.zeroForOne == (params.amountSpecified < 0);
        uint256 total;
        if (nativeIsSpecified) {
            if (nativeAmount != expectedNativePoolAmount) {
                revert PartialFillUnsupported(expectedNativePoolAmount, nativeAmount);
            }
        } else {
            (uint256 gross, uint256 platformFee, uint256 creatorFee, uint256 openingTax) =
                _quoteTradeFees(nativeAmount, params.amountSpecified > 0, params.zeroForOne, activeOpeningTaxPpm);
            total = platformFee + creatorFee + openingTax;
            if (params.amountSpecified < 0 && total >= nativeAmount) revert NoTrade();
            _accrue(sender, key, params.zeroForOne, gross, platformFee, creatorFee, openingTax);
        }
        if (activeBuyer != address(0)) {
            if (delta.amount1() <= 0) revert NoTrade();
            uint256 bought = boughtDuringProtection[activeBuyer] + uint256(uint128(delta.amount1()));
            uint256 limit = ProtectedLaunchTokenV1(token).walletTokenLimit();
            if (bought > limit) revert BuyerLimitExceeded(activeBuyer, bought, limit);
            boughtDuringProtection[activeBuyer] = bought;
            activeBuyer = address(0);
        }
        _afterModule(sender, key, params, delta, data);
        _observeSlot0();
        expectedNativePoolAmount = 0;
        activeSwap = bytes32(0);
        activeOpeningTaxPpm = 0;
        swapActive = false;
        return (IHooks.afterSwap.selector, total.toInt256().toInt128());
    }

    function _beforeModule(address sender, PoolKey calldata key, SwapParams calldata params, bytes calldata data)
        private
        view
        returns (uint24 overrideFee)
    {
        if (_internalActionSender(sender)) return 0;
        if (module == address(0)) return 0;
        _requireModuleCode();
        (bytes4 selector, BeforeSwapDelta customDelta, uint24 fee) =
            IProtectedNativeFeeModuleV1(module).beforeSwap(sender, key, params, data);
        if (selector != IProtectedNativeFeeModuleV1.beforeSwap.selector) revert InvalidModuleResponse();
        if (BeforeSwapDelta.unwrap(customDelta) != 0) revert UnsupportedCustomDelta();
        if (fee != 0) {
            if (!lpFee.isDynamicFee() || !fee.isOverride()) revert InvalidDynamicFeeOverride();
            if (fee.removeOverrideFlagAndValidate() > maxModuleLpFeePips) revert InvalidDynamicFeeOverride();
        }
        return fee;
    }

    function _afterModule(
        address sender,
        PoolKey calldata key,
        SwapParams calldata params,
        BalanceDelta delta,
        bytes calldata data
    ) private view {
        if (_internalActionSender(sender)) return;
        if (module == address(0)) return;
        _requireModuleCode();
        (bytes4 selector, int128 customDelta) =
            IProtectedNativeFeeModuleV1(module).afterSwap(sender, key, params, delta, data);
        if (selector != IProtectedNativeFeeModuleV1.afterSwap.selector) revert InvalidModuleResponse();
        if (customDelta != 0) revert UnsupportedCustomDelta();
    }

    function _requireModuleCode() private view {
        if (module.codehash != moduleCodeHash) revert ModuleCodeChanged();
    }

    function _requirePool(PoolKey calldata key) private view {
        if (
            Currency.unwrap(key.currency0) != address(0) || Currency.unwrap(key.currency1) != token || key.fee != lpFee
                || key.tickSpacing != tickSpacing || address(key.hooks) != address(this)
        ) revert UnexpectedPool();
    }

    function _accrue(
        address sender,
        PoolKey calldata key,
        bool isBuy,
        uint256 gross,
        uint256 platformFee,
        uint256 creatorFee,
        uint256 openingTax
    ) private {
        platformFee.toInt256().toInt128();
        poolManager.mint(address(feeVault), 0, platformFee);
        feeVault.recordFees(platformFee, 0);
        creatorFee.toInt256().toInt128();
        poolManager.mint(address(this), 0, creatorFee);
        _creditProjectFees(creatorFee);
        emit NativeFeesAccrued(keccak256(abi.encode(key)), sender, isBuy, gross, platformFee, creatorFee);
        if (openingTax != 0) {
            openingTax.toInt256().toInt128();
            poolManager.mint(address(openingTaxVault), 0, openingTax);
            openingTaxVault.recordFees(openingTax, 0);
            emit OpeningTaxAccrued(keccak256(abi.encode(key)), sender, gross, openingTax);
        }
    }

    function _creditProjectFees(uint256 amount) private {
        if (amount == 0) return;
        IFeeFlowQaSnapshotToken(token).finalizeSnapshot();
        totalProjectFeesCollected += amount;
        uint256 liquidityShare = Math.mulDiv(amount, 30, 100);
        uint256 buybackShare = Math.mulDiv(amount, 20, 100);
        uint256 holderShare = Math.mulDiv(amount, 20, 100);
        liquidityReserve += liquidityShare;
        buybackReserve += buybackShare;
        holderReserve += holderShare;
        _holderPoolByDay[block.timestamp / 86400] += holderShare;
        creatorReserve += amount - liquidityShare - buybackShare - holderShare;
    }

    /// @notice Claim the funded creator share to the fixed project creator.
    function poolId() external view returns (bytes32) {
        return bytes32(PoolId.unwrap(poolKey().toId()));
    }

    /// @notice Executes one bounded buyback and burn from the buyback reserve; returns false without mutation when not eligible.
    function _internalActionSender(address sender) private view returns(bool) {
        return _actionLocked && (_actionKind==ACTION_BUYBACK || _actionKind==ACTION_LIQUIDITY) && sender==address(_liquidityVault);
    }
    function liquidityVault() external view returns(address) { return address(_liquidityVault); }
    function liquidityPositionOwner() external view returns(address) { return _liquidityVault.owner(); }
    function liquidityPositionLiquidity() external view returns(uint128) { return _liquidityVault.liquidity(); }
    function executeLiquidity() external returns(bool) {
        if(_actionLocked||liquidityReserve<minimumLiquidityDeposit||!_actionPriceReady())return false;
        if(block.timestamp<ProtectedLaunchTokenV1(token).startedAt()+3600||block.timestamp<lastLiquidityAt+3600)return false;
        uint256 budget=liquidityReserve;
        _actionLocked=true;_actionKind=ACTION_LIQUIDITY;_actionAmount=budget;_actionRecipient=address(_liquidityVault);
        if(!poolManager.transfer(address(_liquidityVault),0,budget))revert InvalidAction();
        try _liquidityVault.reinvest(budget) returns(uint256 spent,uint128 added) {
            if(spent==0||spent>budget||added==0)revert InvalidAction();
            liquidityReserve-=spent;lastLiquidityAt=block.timestamp;_clearLiquidityAction();return true;
        } catch { _liquidityVault.refund(budget);_clearLiquidityAction();return false; }
    }
    function _clearLiquidityAction() private { _actionLocked=false;_actionKind=ACTION_NONE;_actionAmount=0;_actionRecipient=address(0);_pendingPayoutHash=0; }
    function executeBuyback() external returns (bool) {
        if (_actionLocked || buybackReserve == 0 || !_actionPriceReady()) return false;
        if (ProtectedLaunchTokenV1(token).startedAt() == 0 || block.timestamp < ProtectedLaunchTokenV1(token).startedAt() + 3600 || block.timestamp < lastBuybackAt + 3600) return false;
        uint256 budget=buybackReserve;_actionLocked=true;_actionKind=ACTION_BUYBACK;_actionAmount=budget;_actionRecipient=address(_liquidityVault);
        if(!poolManager.transfer(address(_liquidityVault),0,budget))revert InvalidAction();
        try _liquidityVault.buyback(budget) returns(uint256 spent,uint256 burned) {
            if(spent==0||spent>budget||burned==0)revert InvalidAction();
            buybackReserve-=spent;lastBuybackAt=block.timestamp;totalBurned+=burned;_clearLiquidityAction();return true;
        } catch {_liquidityVault.refund(budget);_clearLiquidityAction();return false;}
    }

    function onHolderSnapshot(uint256 day,uint256 total) external {
        if(msg.sender!=token||day>=block.timestamp/86400)revert InvalidSnapshot();
        if(total==0){uint256 carry=_holderPoolByDay[day];delete _holderPoolByDay[day];_holderPoolByDay[block.timestamp/86400]+=carry;}
    }
    function claimCreatorShare() external returns (uint256 amount) {
        if (_actionLocked) revert ActionReentrant();
        amount = creatorReserve;
        if (amount == 0) revert NothingClaimable();
        creatorReserve = 0;
        _runPayout(ACTION_CREATOR_CLAIM, amount, projectCreator, 0, address(0));
    }

    /// @notice Claim the holder share of a snapshot for the snapshot holder (permissionless).
    function claimHolder(uint256 id, address account) external returns (uint256 amount) {
        if (_actionLocked) revert ActionReentrant();
        amount = holderClaimable(id, account);
        if (amount == 0) revert NothingClaimable();
        holderClaimed[id][account] = true;
        holderReserve -= amount;
        _runPayout(ACTION_HOLDER_CLAIM, amount, account, id, account);
    }

    /// @notice Claimable holder amount for a snapshot; zero if claimed, invalid or not a snapshot holder.
    function holderClaimable(uint256 id, address account) public view returns (uint256) {
        if (holderClaimed[id][account] || account == address(0)) return 0;
        if (id >= IFeeFlowQaSnapshotToken(token).snapshotCount()) return 0;
        uint256 total = IFeeFlowQaSnapshotToken(token).snapshotTotal(id);
        if (total == 0) return 0;
        (address[10] memory holders, uint256[10] memory balances) = IFeeFlowQaSnapshotToken(token).snapshotHolders(id);
        uint256 pool = snapshotHolderPool(id);
        if (pool == 0) return 0;
        int256 lastIdx = -1;
        uint256 accountBal;
        bool found;
        for (uint256 i; i < 10; ++i) {
            if (balances[i] != 0) lastIdx = int256(i);
            if (holders[i] == account) {
                found = true;
                accountBal = balances[i];
            }
        }
        if (!found || accountBal == 0 || lastIdx < 0) return 0;
        uint256 share = FullMath.mulDiv(pool, accountBal, total);
        if (uint256(lastIdx) == _indexOf(holders, account)) {
            uint256 others;
            for (uint256 i; i < 10; ++i) {
                if (i != uint256(lastIdx) && balances[i] != 0) {
                    others += FullMath.mulDiv(pool, balances[i], total);
                }
            }
            share = pool - others;
        }
        return share;
    }

    function snapshotHolderPool(uint256 id) public view returns (uint256) {
        if (id >= IFeeFlowQaSnapshotToken(token).snapshotCount()) return 0;
        return _holderPoolByDay[IFeeFlowQaSnapshotToken(token).snapshotDay(id)];
    }

    function observationCount() public view returns (uint256) {
        return _observationStored;
    }

    function latestObservation() public view returns (uint256 timestamp, uint160 sqrtPriceX96, int24 tick) {
        if (_observationStored == 0) return (0, 0, 0);
        Observation memory o = _observations[(_observationHead + OBSERVATION_CAPACITY - 1) % OBSERVATION_CAPACITY];
        return (o.timestamp, o.sqrtPriceX96, o.tick);
    }

    function hasSufficientObservation() public view returns (bool) {
        if (_observationStored == 0) return false;
        Observation memory oldest = _observations[_oldestIndex()];
        return block.timestamp >= uint256(oldest.timestamp) + TWAP_MIN_AGE;
    }

    function observedSqrtPriceX96() public view returns (uint160) {
        if (!hasSufficientObservation()) return 0;
        uint256 first = _oldestIndex();
        Observation memory oldest = _observations[first];
        uint64 nowTs = uint64(block.timestamp);
        uint64 cutoff = nowTs - uint64(TWAP_MIN_AGE);
        // Use the newest complete observation at least one hour old. This
        // retains an exact cumulative interval instead of interpolating across
        // unrecorded intra-minute trades or averaging the entire launch age.
        for (uint256 i = 1; i < _observationStored; ++i) {
            Observation memory point = _observations[(first + i) % OBSERVATION_CAPACITY];
            if (point.timestamp > cutoff) break;
            oldest = point;
        }
        uint256 elapsed = uint256(nowTs - oldest.timestamp);
        int128 cumNow = _cumulativeTick + int128(int256(_lastTick)) * int128(int256(uint256(nowTs - _lastObservedAt)));
        int128 diff = cumNow - oldest.tickCumulative;
        int128 period = int128(int256(elapsed));
        int128 mean = diff / period;
        if (diff < 0 && diff % period != 0) mean -= 1;
        return TickMath.getSqrtPriceAtTick(int24(mean));
    }

    function _oldestIndex() private view returns (uint256) {
        if (_observationStored < OBSERVATION_CAPACITY) return 0;
        return _observationHead;
    }

    function _observeSlot0() private {
        PoolKey memory key = poolKey();
        (uint160 sqrtPriceX96, int24 tick,,) = StateLibrary.getSlot0(poolManager, key.toId());
        uint64 nowTs = uint64(block.timestamp);
        if (_observationStored != 0) {
            _cumulativeTick += int128(int256(_lastTick)) * int128(int256(uint256(nowTs - _lastObservedAt)));
        }
        _lastObservedAt = nowTs;
        _lastTick = tick;
        Observation memory point = Observation(nowTs, _cumulativeTick, tick, sqrtPriceX96);
        uint256 lastIndex = (_observationHead + OBSERVATION_CAPACITY - 1) % OBSERVATION_CAPACITY;
        if (_observationStored == 0 || (_observationStored == 1 && nowTs > _lastStoredTimestamp())
            || nowTs / OBSERVATION_MIN_INTERVAL > _lastStoredTimestamp() / OBSERVATION_MIN_INTERVAL) {
            _observations[_observationHead] = point;
            _observationHead = (_observationHead + 1) % OBSERVATION_CAPACITY;
            if (_observationStored < OBSERVATION_CAPACITY) ++_observationStored;
        } else {
            _observations[lastIndex] = point;
        }
    }

    function _lastStoredTimestamp() private view returns (uint256) {
        return _observations[(_observationHead + OBSERVATION_CAPACITY - 1) % OBSERVATION_CAPACITY].timestamp;
    }

    function _actionPriceReady() private view returns (bool) {
        uint160 twap = observedSqrtPriceX96();
        if (twap == 0) return false;
        PoolKey memory key = poolKey();
        (uint160 current,,,) = StateLibrary.getSlot0(poolManager, key.toId());
        if (current == 0) return false;
        uint256 low = FullMath.mulDiv(uint256(twap), 9951, 10_000);
        uint256 high = FullMath.mulDiv(uint256(twap), 10049, 10_000);
        return uint256(current) >= low && uint256(current) <= high;
    }

    function _indexOf(address[10] memory holders, address account) private pure returns (uint256) {
        for (uint256 i; i < 10; ++i) {
            if (holders[i] == account) return i;
        }
        return type(uint256).max;
    }

    function _runPayout(uint8 kind, uint256 amount, address recipient, uint256 id, address account) private {
        _actionLocked = true;
        _actionKind = kind;
        _actionAmount = amount;
        _actionRecipient = recipient;
        bytes memory payload = abi.encode(kind, amount, recipient, id, account);
        _pendingPayoutHash = keccak256(payload);
        poolManager.unlock(payload);
        _pendingPayoutHash = bytes32(0);
        _actionLocked = false;
        _actionKind = ACTION_NONE;
        _actionAmount = 0;
        _actionRecipient = address(0);
    }

    /// @notice Uniswap v4 unlock callback; accepts only the canonical PoolManager with the committed action.
    function unlockCallback(bytes calldata data) external override returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert UnauthorizedCallback();
        if (_pendingPayoutHash == bytes32(0) || keccak256(data) != _pendingPayoutHash) revert InvalidAction();
        if (!_actionLocked || _actionKind == ACTION_NONE) revert InvalidAction();
        (uint8 kind, uint256 amount, address recipient, uint256 id, address account) =
            abi.decode(data, (uint8, uint256, address, uint256, address));
        if (kind != _actionKind || amount != _actionAmount || recipient != _actionRecipient) revert InvalidAction();
        if (kind == ACTION_HOLDER_CLAIM && account != recipient) revert InvalidAction();
        if (kind != ACTION_HOLDER_CLAIM && kind != ACTION_CREATOR_CLAIM) revert InvalidAction();
        poolManager.burn(address(this), 0, amount);
        poolManager.take(Currency.wrap(address(0)), recipient, amount);
        if (kind == ACTION_HOLDER_CLAIM) {
            emit HolderClaimed(id, account, amount);
        } else {
            emit CreatorClaimed(recipient, amount);
        }
        return bytes("");
    }

    event HolderClaimed(uint256 indexed id, address indexed account, uint256 amount);
    event CreatorClaimed(address indexed recipient, uint256 amount);

    function _absolute(int256 amount) private pure returns (uint256) {
        if (amount == type(int256).min) revert InvalidConfiguration();
        return uint256(amount < 0 ? -amount : amount);
    }
}

